function(container, apiUrl, tables) {
  // 業務ロジックモジュールをインポート
  const { collectSalesData, classifySalesDataByProduct, classifySalesDataByStore, filterValidProductData, collectWeatherData, collectEventData, collectSeasonalData, analyzeCorrelationSalesWeather, analyzeCorrelationSalesEvent, analyzeCorrelationSalesSeason, compareWithHistoricalData, findAlternativeComparisonData, validateComparisonPeriod } = window.aivicLogic;

  // 現在の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#order-date').value = today;

  let currentStoreId = '';
  let orderData = [];
  let selectedOrderIds = new Set();

  // 店舗マスタのテーブルインデックス（1番目）
  const storeTableIndex = 1;
  // 発注データのテーブルインデックス（7番目）
  const orderTableIndex = 7;
  // 商品マスタのテーブルインデックス（2番目）
  const productTableIndex = 2;
  // 需要予測結果のテーブルインデックス（6番目）
  const forecastTableIndex = 6;

  // エラー表示関数
  function showError(message) {
    window.aivicNotify.error(message);
  }

  // 成功表示関数
  function showSuccess(message) {
    window.aivicNotify.success(message);
  }

  // ステータスクラス取得
  function getStatusClass(status) {
    switch (status) {
      case '送信済み': return 'status-sent';
      case '送信中': return 'status-sending';
      case 'エラー': return 'status-error';
      default: return 'status-pending';
    }
  }

  // 店舗選択肢を初期化
  async function initStoreOptions() {
    try {
      const stores = await window.aivicApi.list(storeTableIndex);
      const storeSelect = container.querySelector('#store-select');
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';

      if (stores) {
        stores.filter(store => store.有効フラグ).forEach(store => {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        });
      }
    } catch (error) {
      showError('店舗データの取得に失敗しました');
    }
  }

  // 発注データ一覧を描画
  function renderOrderList(orders) {
    const tbody = container.querySelector('#order-list-tbody');

    if (!orders || orders.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="8" class="muted" style="text-align: center; padding: 2rem;">
            発注データがありません
          </td>
        </tr>
      `;
      updateSendButton();
      return;
    }

    tbody.innerHTML = orders.map(order => `
      <tr data-id="${order.発注ID}">
        <td>
          <input type="checkbox" class="order-checkbox" data-id="${order.発注ID}" 
                 ${selectedOrderIds.has(order.発注ID) ? 'checked' : ''}>
        </td>
        <td>${order.商品コード || ''}</td>
        <td>${order.商品名 || ''}</td>
        <td>${order.予測数量 || 0}</td>
        <td>${order.発注数量 || 0}</td>
        <td>${order.仕入先名 || ''}</td>
        <td>¥${(order.発注金額 || 0).toLocaleString()}</td>
        <td>
          <span class="status-badge ${getStatusClass(order.発注ステータス)}">
            ${order.発注ステータス || '未送信'}
          </span>
        </td>
      </tr>
    `).join('');

    // チェックボックスのイベントリスナーを追加
    tbody.querySelectorAll('.order-checkbox').forEach(checkbox => {
      checkbox.addEventListener('change', handleOrderSelection);
    });

    updateSendButton();
  }

  // 発注選択処理
  function handleOrderSelection(event) {
    const orderId = event.target.dataset.id;
    if (event.target.checked) {
      selectedOrderIds.add(orderId);
    } else {
      selectedOrderIds.delete(orderId);
    }
    updateSendButton();
  }

  // 送信ボタンの状態更新
  function updateSendButton() {
    const sendButton = container.querySelector('#send-orders-btn');
    const selectAllCheckbox = container.querySelector('#select-all-orders');

    if (sendButton) {
      sendButton.disabled = selectedOrderIds.size === 0;
    }

    // 全選択チェックボックスの状態更新
    if (selectAllCheckbox && orderData.length > 0) {
      const sendableOrders = orderData.filter(order => order.発注ステータス !== '送信済み');
      selectAllCheckbox.checked = sendableOrders.length > 0 && 
        sendableOrders.every(order => selectedOrderIds.has(order.発注ID));
    }
  }

  // 発注データを読み込み
  async function loadOrderData() {
    if (!currentStoreId) {
      orderData = [];
      renderOrderList([]);
      return;
    }

    try {
      const orders = await window.aivicApi.list(orderTableIndex);
      const products = await window.aivicApi.list(productTableIndex);
      const forecasts = await window.aivicApi.list(forecastTableIndex);

      // 選択された店舗の発注データをフィルタ
      const storeOrders = orders ? orders.filter(order => order.店舗ID === currentStoreId) : [];

      // 商品情報と予測結果を結合
      orderData = storeOrders.map(order => {
        const product = products ? products.find(p => p.商品ID === order.商品ID) : null;
        const forecast = forecasts ? forecasts.find(f => f.商品ID === order.商品ID && f.店舗ID === currentStoreId) : null;

        return {
          ...order,
          商品コード: product?.商品コード || '',
          商品名: product?.商品名 || '',
          予測数量: forecast?.予測数量 || 0,
          仕入先名: product?.仕入先名 || ''
        };
      });

      renderOrderList(orderData);
    } catch (error) {
      showError('発注データの取得に失敗しました');
      orderData = [];
      renderOrderList([]);
    }
  }

  // 発注送信処理
  async function sendOrders() {
    if (selectedOrderIds.size === 0) {
      showError('送信する発注を選択してください');
      return;
    }

    const selectedOrders = orderData.filter(order => selectedOrderIds.has(order.発注ID));
    const sendButton = container.querySelector('#send-orders-btn');

    try {
      sendButton.disabled = true;
      sendButton.textContent = '送信中...';

      // 選択された発注のステータスを「送信中」に更新
      for (const order of selectedOrders) {
        await window.aivicApi.update(orderTableIndex, order.発注ID, {
          ...order,
          発注ステータス: '送信中',
          送信日時: new Date().toISOString()
        });
      }

      // 画面を更新
      await loadOrderData();

      // 実際の送信処理をシミュレート（業務ロジックを使用）
      for (const order of selectedOrders) {
        try {
          // 業務ロジックを使用して発注データを検証・処理
          const salesData = await collectSalesData({
            店舗ID: order.店舗ID,
            商品ID: order.商品ID,
            開始日: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
            終了日: new Date().toISOString().split('T')[0]
          });

          const validatedData = filterValidProductData(salesData);

          if (validatedData.length === 0) {
            throw new Error('有効な販売データが見つかりません');
          }

          // 発注ステータスを「送信済み」に更新
          await window.aivicApi.update(orderTableIndex, order.発注ID, {
            ...order,
            発注ステータス: '送信済み',
            送信完了日時: new Date().toISOString()
          });

        } catch (error) {
          // エラーの場合はステータスを「エラー」に更新
          await window.aivicApi.update(orderTableIndex, order.発注ID, {
            ...order,
            発注ステータス: 'エラー',
            エラーメッセージ: error.message
          });
        }
      }

      selectedOrderIds.clear();
      await loadOrderData();
      showSuccess(`${selectedOrders.length}件の発注を送信しました`);

    } catch (error) {
      showError('発注送信に失敗しました: ' + error.message);
    } finally {
      sendButton.disabled = false;
      sendButton.textContent = '選択した発注を送信';
    }
  }

  // 全選択/全解除処理
  function handleSelectAll(event) {
    const isChecked = event.target.checked;
    const sendableOrders = orderData.filter(order => order.発注ステータス !== '送信済み');

    if (isChecked) {
      sendableOrders.forEach(order => selectedOrderIds.add(order.発注ID));
    } else {
      selectedOrderIds.clear();
    }

    renderOrderList(orderData);
  }

  // イベントリスナーの設定
  function setupEventListeners() {
    // 店舗選択
    const storeSelect = container.querySelector('#store-select');
    if (storeSelect) {
      storeSelect.addEventListener('change', async (event) => {
        currentStoreId = event.target.value;
        selectedOrderIds.clear();
        await loadOrderData();
      });
    }

    // 発注送信ボタン
    const sendButton = container.querySelector('#send-orders-btn');
    if (sendButton) {
      sendButton.addEventListener('click', sendOrders);
    }

    // 全選択チェックボックス
    const selectAllCheckbox = container.querySelector('#select-all-orders');
    if (selectAllCheckbox) {
      selectAllCheckbox.addEventListener('change', handleSelectAll);
    }

    // 更新ボタン
    const refreshButton = container.querySelector('#refresh-orders-btn');
    if (refreshButton) {
      refreshButton.addEventListener('click', async () => {
        await loadOrderData();
        showSuccess('発注データを更新しました');
      });
    }
  }

  // 初期化処理
  async function initialize() {
    await initStoreOptions();
    setupEventListeners();
    updateSendButton();
  }

  // 初期化実行
  initialize().catch(error => {
    showError('画面の初期化に失敗しました: ' + error.message);
  });
}
